import React, { createContext, useContext, useEffect, useState } from 'react';
import { User, Session } from '@supabase/supabase-js';
import { supabase } from '@/integrations/supabase/client';

interface AuthContextType {
  user: User | null;
  session: Session | null;
  loading: boolean;
  signUp: (email: string, password: string, displayName?: string) => Promise<{ error: any }>;
  signIn: (email: string, password: string) => Promise<{ error: any }>;
  signOut: () => Promise<void>;
  resetPassword: (email: string) => Promise<{ error: any }>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
};

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      setUser(session?.user ?? null);
      setLoading(false);
    });

    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setUser(session?.user ?? null);
      setLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  const signUp = async (email: string, password: string, displayName?: string) => {
    const { error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        emailRedirectTo: window.location.origin,
        data: { display_name: displayName },
      },
    });
    return { error };
  };

  const signIn = async (email: string, password: string) => {
    const { error } = await supabase.auth.signInWithPassword({ email, password });
    return { error };
  };

  const signOut = async () => {
    await supabase.auth.signOut();
  };

  const resetPassword = async (email: string) => {
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/reset-password`,
    });
    return { error };
  };

  return (
    <AuthContext.Provider value={{ user, session, loading, signUp, signIn, signOut, resetPassword }}>
      {children}
    </AuthContext.Provider>
  );
};

import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '@/contexts/AuthContext';
import { supabase } from '@/integrations/supabase/client';
import AuroraBackground from '@/components/AuroraBackground';
import { Button } from '@/components/ui/button';
import { useToast } from '@/hooks/use-toast';
import type { DebriefJSON, TranscriptTurn } from '@/types/interview';
import { ArrowLeft, RotateCcw, Star, AlertTriangle, TrendingUp, Calendar, Zap, Clock, Target, MessageSquare } from 'lucide-react';

const SCORE_LABELS: Record<string, string> = {
  communication_clarity: 'Communication',
  structure_star: 'Structure (STAR)',
  role_fit: 'Role Fit',
  confidence_delivery: 'Confidence',
  technical_depth: 'Technical Depth',
};

const Debrief = () => {
  const { id } = useParams<{ id: string }>();
  const { user } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();

  const [debrief, setDebrief] = useState<DebriefJSON | null>(null);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [transcript, setTranscript] = useState<TranscriptTurn[]>([]);

  const fetchDebrief = async () => {
    // Check for existing debrief
    const { data: existing } = await supabase
      .from('session_debriefs')
      .select('debrief_json')
      .eq('session_id', id!)
      .single();

    if (existing?.debrief_json && Object.keys(existing.debrief_json as object).length > 1) {
      setDebrief(existing.debrief_json as unknown as DebriefJSON);
      setLoading(false);
      return;
    }

    // Fetch transcript
    const { data: turns } = await supabase
      .from('transcript_turns')
      .select('*')
      .eq('session_id', id!)
      .order('turn_index', { ascending: true });

    const tt = (turns || []) as TranscriptTurn[];
    setTranscript(tt);

    if (tt.length < 2) {
      setError("We couldn't capture enough transcript data. Please try Chrome or enable microphone access.");
      setLoading(false);
      return;
    }

    // Generate debrief
    await generateDebrief(tt);
  };

  const generateDebrief = async (turns?: TranscriptTurn[]) => {
    setGenerating(true);
    setError(null);
    const turnsToUse = turns || transcript;

    // Fetch session info
    const { data: sessionData } = await supabase
      .from('interview_sessions')
      .select('*')
      .eq('id', id!)
      .single();

    try {
      const { data, error: fnErr } = await supabase.functions.invoke('generate-debrief', {
        body: {
          session: sessionData,
          transcript_turns: turnsToUse,
        },
      });

      if (fnErr) throw fnErr;
      if (!data?.debrief) throw new Error('No debrief returned');

      const debriefData = data.debrief as DebriefJSON;
      setDebrief(debriefData);

      // Save to DB
      const { data: existingDebrief } = await supabase
        .from('session_debriefs')
        .select('id')
        .eq('session_id', id!)
        .single();

      if (existingDebrief) {
        await supabase.from('session_debriefs').update({
          debrief_json: debriefData as any,
        }).eq('session_id', id!);
      } else {
        await supabase.from('session_debriefs').insert({
          session_id: id!,
          debrief_json: debriefData as any,
        });
      }

      // Update session status
      await supabase.from('interview_sessions').update({ status: 'done' }).eq('id', id!);
    } catch (e: any) {
      setError(e.message || 'Failed to generate debrief');
      await supabase.from('interview_sessions').update({ status: 'failed' }).eq('id', id!);
    }
    setGenerating(false);
    setLoading(false);
  };

  useEffect(() => { fetchDebrief(); }, [id]);

  const scoreColor = (score: number) => {
    if (score >= 75) return 'text-accent';
    if (score >= 50) return 'text-warning';
    return 'text-destructive';
  };

  if (loading || generating) {
    return (
      <div className="relative min-h-screen noise-bg">
        <AuroraBackground />
        <div className="relative z-10 flex min-h-screen flex-col items-center justify-center gap-4">
          <div className="h-12 w-12 animate-spin rounded-full border-3 border-primary border-t-transparent" />
          <h2 className="font-display text-heading">Generating Debrief…</h2>
          <p className="text-sm text-muted-foreground">Analyzing your interview performance</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="relative min-h-screen noise-bg">
        <AuroraBackground />
        <div className="relative z-10 flex min-h-screen flex-col items-center justify-center gap-4 px-4">
          <AlertTriangle className="h-12 w-12 text-destructive" />
          <h2 className="font-display text-heading">Debrief Error</h2>
          <p className="max-w-md text-center text-muted-foreground">{error}</p>
          <div className="flex gap-3">
            <Button onClick={() => { setLoading(true); fetchDebrief(); }}>
              <RotateCcw className="mr-1 h-4 w-4" /> Retry
            </Button>
            <Button variant="outline" onClick={() => navigate('/dashboard')}>
              Back to Dashboard
            </Button>
          </div>
        </div>
      </div>
    );
  }

  if (!debrief) return null;

  return (
    <div className="relative min-h-screen noise-bg">
      <AuroraBackground />
      <div className="relative z-10 mx-auto max-w-[1100px] px-4 py-8">
        <div className="mb-6 flex items-center justify-between">
          <button onClick={() => navigate('/dashboard')} className="flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground">
            <ArrowLeft className="h-4 w-4" /> Dashboard
          </button>
          <Button variant="outline" size="sm" onClick={() => generateDebrief()}>
            <RotateCcw className="mr-1 h-4 w-4" /> Regenerate
          </Button>
        </div>

        {/* Summary header */}
        <div className="mb-8 glass rounded-xl p-6 shadow-card">
          <div className="flex flex-col items-center gap-4 sm:flex-row sm:items-start">
            <div className="flex flex-col items-center gap-2 sm:items-start">
              <div className="flex items-center gap-2">
                <span className="rounded-full bg-primary/10 px-3 py-1 text-xs font-medium capitalize text-primary">
                  {debrief.session_summary.interview_type}
                </span>
                <span className="rounded-full bg-muted px-3 py-1 text-xs font-medium capitalize">
                  {debrief.session_summary.difficulty}
                </span>
                {debrief.session_summary.session_status === 'ended_early' && (
                  <span className="rounded-full bg-warning/10 px-3 py-1 text-xs font-medium text-warning">Partial</span>
                )}
              </div>
              <h1 className="font-display text-display">
                {debrief.session_summary.company || 'Interview'} Debrief
              </h1>
              <p className="text-sm text-muted-foreground">
                {debrief.session_summary.role_guess} · {debrief.session_summary.actual_duration_minutes} min
              </p>
              {debrief.notes_if_low_data && (
                <p className="mt-1 text-xs text-warning">{debrief.notes_if_low_data}</p>
              )}
            </div>
            {/* Overall score */}
            <div className="ml-auto flex flex-col items-center">
              <div className={`animate-score-reveal flex h-24 w-24 items-center justify-center rounded-full border-4 ${scoreColor(debrief.scores.overall)} border-current`}>
                <span className="font-display text-3xl font-bold">{debrief.scores.overall}</span>
              </div>
              <p className="mt-1 text-sm font-medium">Overall</p>
            </div>
          </div>
        </div>

        {/* Category scores */}
        <div className="mb-8 grid grid-cols-2 gap-3 sm:grid-cols-5">
          {Object.entries(SCORE_LABELS).map(([key, label]) => {
            const score = debrief.scores[key as keyof typeof debrief.scores] as number;
            return (
              <div key={key} className="glass rounded-xl p-4 text-center shadow-card">
                <p className={`font-display text-2xl font-bold ${scoreColor(score)}`}>{score}</p>
                <p className="mt-1 text-xs text-muted-foreground">{label}</p>
              </div>
            );
          })}
        </div>

        {/* Topics discussed */}
        {debrief.session_summary.topics_discussed.length > 0 && (
          <section className="mb-8">
            <h2 className="mb-4 font-display text-heading flex items-center gap-2">
              <MessageSquare className="h-5 w-5" /> Topics Discussed
            </h2>
            <div className="glass rounded-xl p-6 shadow-card space-y-3">
              {debrief.session_summary.topics_discussed.map((t, i) => (
                <div key={i}>
                  <p className="font-medium">{t.topic}</p>
                  <ul className="ml-4 mt-1 list-disc text-sm text-muted-foreground">
                    {t.notes.map((n, j) => <li key={j}>{n}</li>)}
                  </ul>
                </div>
              ))}
            </div>
          </section>
        )}

        <div className="grid gap-8 lg:grid-cols-2">
          {/* Strengths */}
          <section>
            <h2 className="mb-4 font-display text-heading flex items-center gap-2">
              <Star className="h-5 w-5 text-accent" /> Strengths
            </h2>
            <div className="space-y-3">
              {debrief.strengths.map((s, i) => (
                <div key={i} className="glass rounded-xl p-5 shadow-card animate-fade-slide-up" style={{ animationDelay: `${i * 100}ms` }}>
                  <p className="font-medium">{s.title}</p>
                  <p className="mt-1 text-sm text-muted-foreground">{s.why_it_matters}</p>
                  {s.evidence.quote && (
                    <blockquote className="mt-2 border-l-2 border-accent pl-3 text-sm italic text-muted-foreground">
                      "{s.evidence.quote}"
                    </blockquote>
                  )}
                </div>
              ))}
            </div>
          </section>

          {/* Improvements */}
          <section>
            <h2 className="mb-4 font-display text-heading flex items-center gap-2">
              <TrendingUp className="h-5 w-5 text-primary" /> Areas to Improve
            </h2>
            <div className="space-y-3">
              {debrief.improvements.map((imp, i) => (
                <div key={i} className="glass rounded-xl p-5 shadow-card animate-fade-slide-up" style={{ animationDelay: `${i * 100}ms` }}>
                  <p className="font-medium">{imp.title}</p>
                  <p className="mt-1 text-sm text-muted-foreground">{imp.issue}</p>
                  {imp.evidence.quote && (
                    <blockquote className="mt-2 border-l-2 border-destructive pl-3 text-sm italic text-muted-foreground">
                      "{imp.evidence.quote}"
                    </blockquote>
                  )}
                  {imp.better_answer_example && (
                    <div className="mt-2 rounded-lg bg-accent/5 p-3">
                      <p className="text-xs font-medium text-accent">Better answer:</p>
                      <p className="text-sm">{imp.better_answer_example}</p>
                    </div>
                  )}
                  {imp.micro_exercise && (
                    <p className="mt-2 text-xs text-muted-foreground">💡 Exercise: {imp.micro_exercise}</p>
                  )}
                </div>
              ))}
            </div>
          </section>
        </div>

        {/* Delivery metrics */}
        <section className="mt-8 mb-8">
          <h2 className="mb-4 font-display text-heading flex items-center gap-2">
            <Zap className="h-5 w-5" /> Delivery Metrics
          </h2>
          <div className="grid grid-cols-3 gap-3">
            <div className="glass rounded-xl p-4 text-center shadow-card">
              <p className="font-display text-2xl font-bold">{debrief.delivery_metrics.filler_word_estimate}</p>
              <p className="text-xs text-muted-foreground">Filler words</p>
            </div>
            <div className="glass rounded-xl p-4 text-center shadow-card">
              <p className="font-display text-2xl font-bold">{debrief.delivery_metrics.pace_wpm_estimate}</p>
              <p className="text-xs text-muted-foreground">WPM</p>
            </div>
            <div className="glass rounded-xl p-4 text-center shadow-card">
              <p className="font-display text-2xl font-bold">{debrief.delivery_metrics.long_pause_estimate}</p>
              <p className="text-xs text-muted-foreground">Long pauses</p>
            </div>
          </div>
        </section>

        {/* Moments that mattered */}
        {debrief.moments_that_mattered.length > 0 && (
          <section className="mb-8">
            <h2 className="mb-4 font-display text-heading flex items-center gap-2">
              <Target className="h-5 w-5" /> Moments That Mattered
            </h2>
            <div className="space-y-2">
              {debrief.moments_that_mattered.map((m, i) => (
                <div key={i} className="glass flex items-center gap-3 rounded-xl p-4 shadow-card">
                  <Clock className="h-4 w-4 shrink-0 text-primary" />
                  <div className="flex-1">
                    <p className="font-medium">{m.label}</p>
                    <p className="text-sm text-muted-foreground">{m.reason}</p>
                  </div>
                  <span className="text-xs text-muted-foreground">{m.timestamp_start}</span>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* 7-day plan */}
        {debrief.practice_plan_7_days.length > 0 && (
          <section className="mb-8">
            <h2 className="mb-4 font-display text-heading flex items-center gap-2">
              <Calendar className="h-5 w-5" /> 7-Day Practice Plan
            </h2>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {debrief.practice_plan_7_days.map(day => (
                <div key={day.day} className="glass rounded-xl p-4 shadow-card">
                  <div className="flex items-center justify-between">
                    <p className="font-medium">Day {day.day}</p>
                    <span className="text-xs text-muted-foreground">{day.time_minutes} min</span>
                  </div>
                  <p className="mt-1 text-sm text-primary">{day.focus}</p>
                  <ul className="mt-2 space-y-1">
                    {day.tasks.map((t, i) => (
                      <li key={i} className="flex items-start gap-1 text-xs text-muted-foreground">
                        <span className="mt-0.5">•</span> {t}
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </div>
          </section>
        )}
      </div>
    </div>
  );
};

export default Debrief;

import { useState, useEffect, useRef, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '@/contexts/AuthContext';
import { supabase } from '@/integrations/supabase/client';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useToast } from '@/hooks/use-toast';
import type { InterviewSession, TranscriptTurn } from '@/types/interview';
import { Mic, MicOff, Square, MessageSquare, Clock, Send, BookmarkPlus, ChevronRight } from 'lucide-react';

const InterviewRoom = () => {
  const { id } = useParams<{ id: string }>();
  const { user } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();

  const [session, setSession] = useState<InterviewSession | null>(null);
  const [transcript, setTranscript] = useState<TranscriptTurn[]>([]);
  const [isListening, setIsListening] = useState(false);
  const [textMode, setTextMode] = useState(false);
  const [textInput, setTextInput] = useState('');
  const [currentSpeaker, setCurrentSpeaker] = useState<'InterviewerA' | 'Candidate'>('InterviewerA');
  const [interviewerSpeaking, setInterviewerSpeaking] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [ending, setEnding] = useState(false);
  const [waitingForAI, setWaitingForAI] = useState(false);

  const recognitionRef = useRef<any>(null);
  const synthRef = useRef(window.speechSynthesis);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const startTimeRef = useRef<number>(Date.now());
  const timerRef = useRef<number>();
  const turnIndexRef = useRef(0);
  const transcriptRef = useRef<TranscriptTurn[]>([]);

  // Keep transcriptRef in sync
  useEffect(() => { transcriptRef.current = transcript; }, [transcript]);

  // Fetch session
  useEffect(() => {
    if (!id) return;
    supabase.from('interview_sessions').select('*').eq('id', id).single()
      .then(({ data }) => {
        if (data) setSession(data as InterviewSession);
      });
  }, [id]);

  // Timer
  useEffect(() => {
    startTimeRef.current = Date.now();
    timerRef.current = window.setInterval(() => {
      setElapsed(Math.floor((Date.now() - startTimeRef.current) / 1000));
    }, 1000);
    return () => clearInterval(timerRef.current);
  }, []);

  // Start audio recording
  useEffect(() => {
    navigator.mediaDevices.getUserMedia({ audio: true }).then(stream => {
      const mr = new MediaRecorder(stream);
      mediaRecorderRef.current = mr;
      mr.ondataavailable = e => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      mr.start(5000); // chunk every 5s
    }).catch(() => {
      // Can't record - that's ok, text mode still works
    });
    return () => { mediaRecorderRef.current?.stop(); };
  }, []);

  // Start with interviewer greeting
  useEffect(() => {
    if (session) {
      const greeting = getGreeting(session);
      addInterviewerTurn(greeting);
    }
  }, [session]);

  const getGreeting = (s: InterviewSession) => {
    const name = user?.user_metadata?.display_name || 'there';
    const company = s.company || 'our company';
    if (s.difficulty === 'easy') return `Hi ${name}! Welcome, I'm excited to chat with you today about the ${s.role_title || 'role'} at ${company}. This will be a relaxed conversation — just be yourself. Let's start: Can you tell me a bit about yourself and what drew you to this opportunity?`;
    if (s.difficulty === 'hard') return `Let's begin. I'm interviewing you for the ${s.role_title || 'position'} at ${company}. I'll be direct — I need to see concrete evidence of your capabilities. Start by telling me your most impactful achievement in the last two years. Be specific with numbers.`;
    return `Good to meet you. I'll be conducting your ${s.interview_type} interview for the ${s.role_title || 'role'} at ${company}. Let's get started. Tell me about yourself and why you're interested in this position.`;
  };

  const addInterviewerTurn = useCallback((text: string) => {
    const turn: TranscriptTurn = {
      speaker: 'InterviewerA',
      text,
      timestamp_start: (Date.now() - startTimeRef.current) / 1000,
      turn_index: turnIndexRef.current++,
    };
    setTranscript(prev => [...prev, turn]);
    setCurrentSpeaker('InterviewerA');
    setInterviewerSpeaking(true);

    // Save to DB
    if (id) {
      supabase.from('transcript_turns').insert({
        session_id: id,
        speaker: turn.speaker,
        text: turn.text,
        timestamp_start: turn.timestamp_start,
        timestamp_end: (Date.now() - startTimeRef.current) / 1000,
        turn_index: turn.turn_index,
      }).then(() => {});
    }

    // Speak
    const utter = new SpeechSynthesisUtterance(text);
    utter.rate = 0.95;
    utter.pitch = 1.0;
    const voices = synthRef.current.getVoices();
    const preferredVoice = voices.find(v => v.lang.startsWith('en') && v.name.includes('Google')) || voices.find(v => v.lang.startsWith('en'));
    if (preferredVoice) utter.voice = preferredVoice;
    utter.onend = () => {
      setInterviewerSpeaking(false);
      setCurrentSpeaker('Candidate');
    };
    synthRef.current.speak(utter);
  }, [id]);

  // Speech recognition setup
  const startListening = useCallback(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      setTextMode(true);
      toast({ title: 'Speech not supported', description: 'Using text mode instead.' });
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = 'en-US';
    let finalTranscript = '';

    recognition.onresult = (event: any) => {
      let interim = '';
      for (let i = event.resultIndex; i < event.results.length; i++) {
        if (event.results[i].isFinal) finalTranscript += event.results[i][0].transcript + ' ';
        else interim += event.results[i][0].transcript;
      }
    };

    recognition.onend = () => {
      if (finalTranscript.trim()) {
        submitCandidateAnswer(finalTranscript.trim());
      }
      setIsListening(false);
    };

    recognition.onerror = () => {
      setIsListening(false);
      setTextMode(true);
    };

    recognitionRef.current = recognition;
    recognition.start();
    setIsListening(true);
  }, []);

  const stopListening = () => {
    recognitionRef.current?.stop();
    setIsListening(false);
  };

  const submitCandidateAnswer = async (text: string) => {
    const turn: TranscriptTurn = {
      speaker: 'Candidate',
      text,
      timestamp_start: (Date.now() - startTimeRef.current) / 1000,
      turn_index: turnIndexRef.current++,
    };
    setTranscript(prev => [...prev, turn]);

    // Save to DB
    if (id) {
      await supabase.from('transcript_turns').insert({
        session_id: id,
        speaker: 'Candidate',
        text,
        timestamp_start: turn.timestamp_start,
        timestamp_end: (Date.now() - startTimeRef.current) / 1000,
        turn_index: turn.turn_index,
      });
    }

    // Get AI follow-up
    setWaitingForAI(true);
    try {
      const { data, error } = await supabase.functions.invoke('generate-question', {
        body: {
          session_config: session,
          transcript: [...transcriptRef.current, turn],
        },
      });
      if (error) throw error;
      const nextQ = data?.question || "Can you elaborate on that?";
      addInterviewerTurn(nextQ);
    } catch {
      addInterviewerTurn("Interesting. Can you tell me more about that?");
    }
    setWaitingForAI(false);
  };

  const handleTextSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!textInput.trim()) return;
    submitCandidateAnswer(textInput.trim());
    setTextInput('');
  };

  const endInterview = async () => {
    setEnding(true);
    synthRef.current.cancel();
    recognitionRef.current?.stop();
    mediaRecorderRef.current?.stop();

    const durationActual = Math.round(elapsed / 60);
    const plannedMin = session?.duration_planned || 30;
    const status = durationActual < plannedMin ? 'ended_early' : 'completed';

    // Upload audio if available
    let audioUrl: string | undefined;
    if (audioChunksRef.current.length > 0) {
      const blob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
      const path = `${user!.id}/${id}.webm`;
      const { error: uploadErr } = await supabase.storage.from('interview-audio').upload(path, blob, { upsert: true });
      if (!uploadErr) audioUrl = path;
    }

    // Update session
    await supabase.from('interview_sessions').update({
      status: 'debrief_generating',
      duration_actual: durationActual,
      audio_url: audioUrl || null,
    }).eq('id', id!);

    // Navigate to debrief (which will trigger generation)
    navigate(`/debrief/${id}`);
  };

  const formatTime = (s: number) => {
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return `${m}:${sec.toString().padStart(2, '0')}`;
  };

  if (!session) return (
    <div className="flex min-h-screen items-center justify-center">
      <div className="h-8 w-8 animate-spin rounded-full border-2 border-primary border-t-transparent" />
    </div>
  );

  return (
    <div className="flex min-h-screen flex-col bg-background">
      {/* Top bar */}
      <header className="flex items-center justify-between border-b px-4 py-3">
        <div className="flex items-center gap-3">
          <span className="rounded-full bg-primary/10 px-3 py-1 text-xs font-medium capitalize text-primary">{session.interview_type}</span>
          <span className="rounded-full bg-muted px-3 py-1 text-xs font-medium capitalize">{session.difficulty}</span>
        </div>
        <div className="flex items-center gap-2 font-mono text-sm">
          <Clock className="h-4 w-4 text-muted-foreground" />
          <span>{formatTime(elapsed)}</span>
          <span className="text-muted-foreground">/ {session.duration_planned}:00</span>
        </div>
        <Button variant="destructive" size="sm" onClick={endInterview} disabled={ending}>
          <Square className="mr-1 h-3 w-3" /> End
        </Button>
      </header>

      {/* Interview area */}
      <div className="flex flex-1 flex-col">
        {/* Interviewer avatar */}
        <div className="flex flex-col items-center gap-4 py-8">
          <div className={`flex h-20 w-20 items-center justify-center rounded-full bg-primary/10 text-2xl transition-all ${
            interviewerSpeaking ? 'speaking-ring' : ''
          }`}>
            👤
          </div>
          <div className="text-center">
            <p className="font-display font-semibold">Interviewer</p>
            <p className="text-sm text-muted-foreground">
              {interviewerSpeaking ? 'Speaking…' : waitingForAI ? 'Thinking…' : currentSpeaker === 'Candidate' ? 'Your turn' : ''}
            </p>
          </div>

          {/* Waveform */}
          {interviewerSpeaking && (
            <div className="flex items-center gap-1">
              {[...Array(5)].map((_, i) => (
                <div
                  key={i}
                  className="w-1 rounded-full bg-primary"
                  style={{
                    height: '4px',
                    animation: `waveform-bar 0.6s ease-in-out ${i * 0.1}s infinite`,
                  }}
                />
              ))}
            </div>
          )}
        </div>

        {/* Transcript / Captions */}
        <div className="mx-auto max-w-[700px] flex-1 overflow-auto px-4">
          <div className="space-y-3 pb-4">
            {transcript.map((t, i) => (
              <div key={i} className={`flex gap-3 animate-fade-slide-up ${t.speaker === 'Candidate' ? 'flex-row-reverse' : ''}`}>
                <div className={`max-w-[80%] rounded-2xl px-4 py-3 text-sm ${
                  t.speaker === 'Candidate'
                    ? 'bg-primary text-primary-foreground'
                    : 'glass'
                }`}>
                  <p className="mb-1 text-xs font-medium opacity-70">{t.speaker === 'Candidate' ? 'You' : 'Interviewer'}</p>
                  <p>{t.text}</p>
                </div>
              </div>
            ))}
            {waitingForAI && (
              <div className="flex gap-3">
                <div className="glass rounded-2xl px-4 py-3 text-sm">
                  <div className="flex gap-1">
                    <div className="h-2 w-2 animate-bounce rounded-full bg-muted-foreground" style={{ animationDelay: '0ms' }} />
                    <div className="h-2 w-2 animate-bounce rounded-full bg-muted-foreground" style={{ animationDelay: '150ms' }} />
                    <div className="h-2 w-2 animate-bounce rounded-full bg-muted-foreground" style={{ animationDelay: '300ms' }} />
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Input area */}
        <div className="border-t bg-card p-4">
          <div className="mx-auto flex max-w-[700px] items-center gap-3">
            {textMode ? (
              <form onSubmit={handleTextSubmit} className="flex flex-1 gap-2">
                <Input
                  value={textInput}
                  onChange={e => setTextInput(e.target.value)}
                  placeholder="Type your answer…"
                  disabled={interviewerSpeaking || waitingForAI}
                  autoFocus
                />
                <Button type="submit" size="icon" disabled={!textInput.trim() || interviewerSpeaking || waitingForAI}>
                  <Send className="h-4 w-4" />
                </Button>
              </form>
            ) : (
              <Button
                size="lg"
                className={`flex-1 gap-2 rounded-xl py-6 ${isListening ? 'bg-destructive hover:bg-destructive/90' : ''}`}
                onClick={isListening ? stopListening : startListening}
                disabled={interviewerSpeaking || waitingForAI}
              >
                {isListening ? <MicOff className="h-5 w-5" /> : <Mic className="h-5 w-5" />}
                {isListening ? 'Stop Recording' : 'Push to Talk'}
              </Button>
            )}
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setTextMode(!textMode)}
              title={textMode ? 'Switch to voice' : 'Switch to text'}
            >
              {textMode ? <Mic className="h-4 w-4" /> : <MessageSquare className="h-4 w-4" />}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

