const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const { session, transcript_turns } = await req.json();
    const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY");
    if (!GEMINI_API_KEY) throw new Error("GEMINI_API_KEY not configured");

    const turns = transcript_turns || [];
    const turnCount = turns.length;
    const candidateTurns = turns.filter((t: any) => t.speaker === "Candidate");

    if (turnCount < 2) {
      return new Response(JSON.stringify({
        error: "Not enough transcript data",
        debrief: null,
      }), { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } });
    }

    const transcriptText = turns
      .map((t: any) => `[${Math.round(t.timestamp_start)}s] ${t.speaker}: ${t.text}`)
      .join("\n");

    const durationActual = session?.duration_actual || Math.round((turns[turns.length - 1]?.timestamp_start || 0) / 60);
    const sessionStatus = session?.status === "ended_early" || session?.status === "debrief_generating"
      ? (durationActual < (session?.duration_planned || 30) ? "ended_early" : "completed")
      : "completed";

    const isShortSession = turnCount < 6;

    const systemPrompt = `You are an expert interview coach AI. Analyze the following interview transcript and produce a comprehensive debrief.

${isShortSession ? "NOTE: This was a short/partial session. Still score based on available data but add a note about lower confidence." : ""}

You MUST return a valid JSON object matching this EXACT schema. All scores must be 1-100, NEVER 0.

{
  "session_summary": {
    "session_status": "${sessionStatus}",
    "planned_duration_minutes": ${session?.duration_planned || 30},
    "actual_duration_minutes": ${durationActual},
    "role_guess": "${session?.role_title || ""}",
    "company": "${session?.company || ""}",
    "interview_type": "${session?.interview_type || "behavioral"}",
    "difficulty": "${session?.difficulty || "medium"}",
    "topics_discussed": [{"topic":"string","notes":["string"]}]
  },
  "scores": {
    "overall": number (1-100),
    "communication_clarity": number (1-100),
    "structure_star": number (1-100),
    "role_fit": number (1-100),
    "confidence_delivery": number (1-100),
    "technical_depth": number (1-100)
  },
  "strengths": [
    {"title":"string","evidence":{"timestamp_start":"string","timestamp_end":"string","quote":"string"},"why_it_matters":"string"}
  ],
  "improvements": [
    {"title":"string","issue":"string","evidence":{"timestamp_start":"string","timestamp_end":"string","quote":"string"},"better_answer_example":"string","micro_exercise":"string"}
  ],
  "delivery_metrics": {
    "filler_word_estimate": number,
    "pace_wpm_estimate": number,
    "long_pause_estimate": number
  },
  "moments_that_mattered": [
    {"label":"string","timestamp_start":"string","timestamp_end":"string","reason":"string"}
  ],
  "practice_plan_7_days": [
    {"day":number,"focus":"string","tasks":["string"],"time_minutes":number}
  ],
  "notes_if_low_data": "string or empty"
}

Rules:
- Scores MUST be 1-100, NEVER 0
- Provide at least 3 strengths and 3 improvements (or as many as data allows for very short sessions)
- Use actual quotes from transcript as evidence
- Timestamps should reference actual transcript times
- If session is short, still score but note lower confidence in notes_if_low_data
- practice_plan_7_days should have 7 entries with 10-20 min/day tasks
- Be specific and actionable, not generic`;

    const response = await fetch("https://generativelanguage.googleapis.com/v1beta/openai/chat/completions", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${GEMINI_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "google/gemini-3-flash-preview",
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: `Interview transcript:\n\n${transcriptText}\n\nGenerate the debrief JSON.` },
        ],
        tools: [
          {
            type: "function",
            function: {
              name: "generate_debrief",
              description: "Generate a structured interview debrief report",
              parameters: {
                type: "object",
                properties: {
                  session_summary: {
                    type: "object",
                    properties: {
                      session_status: { type: "string" },
                      planned_duration_minutes: { type: "number" },
                      actual_duration_minutes: { type: "number" },
                      role_guess: { type: "string" },
                      company: { type: "string" },
                      interview_type: { type: "string" },
                      difficulty: { type: "string" },
                      topics_discussed: {
                        type: "array",
                        items: {
                          type: "object",
                          properties: {
                            topic: { type: "string" },
                            notes: { type: "array", items: { type: "string" } },
                          },
                          required: ["topic", "notes"],
                        },
                      },
                    },
                    required: ["session_status", "planned_duration_minutes", "actual_duration_minutes", "role_guess", "company", "interview_type", "difficulty", "topics_discussed"],
                  },
                  scores: {
                    type: "object",
                    properties: {
                      overall: { type: "number" },
                      communication_clarity: { type: "number" },
                      structure_star: { type: "number" },
                      role_fit: { type: "number" },
                      confidence_delivery: { type: "number" },
                      technical_depth: { type: "number" },
                    },
                    required: ["overall", "communication_clarity", "structure_star", "role_fit", "confidence_delivery", "technical_depth"],
                  },
                  strengths: {
                    type: "array",
                    items: {
                      type: "object",
                      properties: {
                        title: { type: "string" },
                        evidence: {
                          type: "object",
                          properties: {
                            timestamp_start: { type: "string" },
                            timestamp_end: { type: "string" },
                            quote: { type: "string" },
                          },
                          required: ["timestamp_start", "timestamp_end", "quote"],
                        },
                        why_it_matters: { type: "string" },
                      },
                      required: ["title", "evidence", "why_it_matters"],
                    },
                  },
                  improvements: {
                    type: "array",
                    items: {
                      type: "object",
                      properties: {
                        title: { type: "string" },
                        issue: { type: "string" },
                        evidence: {
                          type: "object",
                          properties: {
                            timestamp_start: { type: "string" },
                            timestamp_end: { type: "string" },
                            quote: { type: "string" },
                          },
                          required: ["timestamp_start", "timestamp_end", "quote"],
                        },
                        better_answer_example: { type: "string" },
                        micro_exercise: { type: "string" },
                      },
                      required: ["title", "issue", "evidence", "better_answer_example", "micro_exercise"],
                    },
                  },
                  delivery_metrics: {
                    type: "object",
                    properties: {
                      filler_word_estimate: { type: "number" },
                      pace_wpm_estimate: { type: "number" },
                      long_pause_estimate: { type: "number" },
                    },
                    required: ["filler_word_estimate", "pace_wpm_estimate", "long_pause_estimate"],
                  },
                  moments_that_mattered: {
                    type: "array",
                    items: {
                      type: "object",
                      properties: {
                        label: { type: "string" },
                        timestamp_start: { type: "string" },
                        timestamp_end: { type: "string" },
                        reason: { type: "string" },
                      },
                      required: ["label", "timestamp_start", "timestamp_end", "reason"],
                    },
                  },
                  practice_plan_7_days: {
                    type: "array",
                    items: {
                      type: "object",
                      properties: {
                        day: { type: "number" },
                        focus: { type: "string" },
                        tasks: { type: "array", items: { type: "string" } },
                        time_minutes: { type: "number" },
                      },
                      required: ["day", "focus", "tasks", "time_minutes"],
                    },
                  },
                  notes_if_low_data: { type: "string" },
                },
                required: ["session_summary", "scores", "strengths", "improvements", "delivery_metrics", "moments_that_mattered", "practice_plan_7_days", "notes_if_low_data"],
              },
            },
          },
        ],
        tool_choice: { type: "function", function: { name: "generate_debrief" } },
      }),
    });

    if (!response.ok) {
      const status = response.status;
      if (status === 429) {
        return new Response(JSON.stringify({ error: "Rate limit exceeded" }), {
          status: 429, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      if (status === 402) {
        return new Response(JSON.stringify({ error: "Payment required" }), {
          status: 402, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      const text = await response.text();
      console.error("AI gateway error:", status, text);
      throw new Error(`AI gateway error: ${status}`);
    }

    const data = await response.json();

    let debrief;
    // Try tool call first
    const toolCall = data.choices?.[0]?.message?.tool_calls?.[0];
    if (toolCall?.function?.arguments) {
      debrief = typeof toolCall.function.arguments === "string"
        ? JSON.parse(toolCall.function.arguments)
        : toolCall.function.arguments;
    } else {
      // Fallback: try parsing from content
      const content = data.choices?.[0]?.message?.content || "";
      const jsonMatch = content.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        debrief = JSON.parse(jsonMatch[0]);
      } else {
        throw new Error("Could not parse debrief from AI response");
      }
    }

    // Validate scores are never 0
    if (debrief.scores) {
      for (const key of Object.keys(debrief.scores)) {
        if (debrief.scores[key] === 0) {
          debrief.scores[key] = Math.max(15, Math.floor(Math.random() * 30) + 20);
        }
      }
    }

    return new Response(JSON.stringify({ debrief }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (e) {
    console.error("generate-debrief error:", e);
    return new Response(JSON.stringify({ error: e instanceof Error ? e.message : "Unknown error" }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const { session_config, transcript } = await req.json();
    const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY");
    if (!GEMINI_API_KEY) throw new Error("GEMINI_API_KEY not configured");

    const difficulty = session_config?.difficulty || "medium";
    const interviewType = session_config?.interview_type || "behavioral";
    const company = session_config?.company || "the company";
    const role = session_config?.role_title || "the role";
    const jd = session_config?.job_description || "";

    const difficultyPrompt = {
      easy: `You are a warm, supportive interviewer. Help the candidate succeed. If their answer is vague, gently guide them: "Could you share a concrete example?" Encourage STAR method. Give small hints.`,
      medium: `You are a professional, neutral interviewer. Ask probing follow-ups when answers lack metrics, tradeoffs, or specifics. Minimal encouragement, more probing.`,
      hard: `You are a strict, blunt-but-professional interviewer on a skeptical panel. You are NOT agreeable by default. Call out weak answers directly: "That's vague. Give me a specific example and measurable impact." "You didn't answer the question. Start with the outcome, then the steps." "What was YOUR role exactly? What did YOU do?" Push for numbers, edge cases, tradeoffs. Reject hand-wavy claims.`,
    }[difficulty] || "";

    const transcriptText = transcript
      .map((t: any) => `${t.speaker}: ${t.text}`)
      .join("\n");

    const systemPrompt = `You are conducting a ${interviewType} interview for ${role} at ${company}.
${difficultyPrompt}

${jd ? `Job Description: ${jd}` : ""}

Rules:
- Ask ONE question at a time
- Questions must be grounded in the conversation context
- After each answer, decide follow-up based on gaps: vagueness, missing metrics, unclear ownership, contradictions, shallow detail
- For technical interviews: ask for complexity, edge cases, alternatives
- Do NOT repeat questions already asked
- Return ONLY the next question text, nothing else`;

    const response = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${GEMINI_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "google/gemini-3-flash-preview",
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: `Here is the interview transcript so far:\n\n${transcriptText}\n\nGenerate the next interviewer question.` },
        ],
      }),
    });

    if (!response.ok) {
      const status = response.status;
      if (status === 429) {
        return new Response(JSON.stringify({ error: "Rate limit exceeded" }), {
          status: 429, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      if (status === 402) {
        return new Response(JSON.stringify({ error: "Payment required" }), {
          status: 402, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      throw new Error(`AI gateway error: ${status}`);
    }

    const data = await response.json();
    const question = data.choices?.[0]?.message?.content?.trim() || "Can you tell me more about that?";

    return new Response(JSON.stringify({ question }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (e) {
    console.error("generate-question error:", e);
    return new Response(JSON.stringify({ error: e instanceof Error ? e.message : "Unknown error", question: "Can you elaborate on your experience with that?" }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

